import {uid,dayOf,ensureDay,effectiveDate,clockNow,eventStamp,addDays,habitDue,habitCount} from './core.js';
import {CATEGORY_LABELS,MEASURES,recordedFactors,rangeRows,compareDays,numericRelations,beforeAfter} from './analysis.js';

export function createEnhancements(api){
 const {esc,icon,btn,textField,options,actions,prettyDate,weekday,showModal,toast,persist,render,navigate}=api;
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
 const modal=()=>$('#modal'),listKeys={med:'meds',symptom:'symptoms',drink:'drinks',activity:'activities'};
 let memoryMode='album',memoryMonth=effectiveDate().slice(0,7),memoryAll=true,photoDate='',analysisRange=30,factorKey='',outcomeKey='mood',lag=0,historyMode='memories';
 const fmt=(n,digits=1)=>n==null?'—':n.toLocaleString('pl',{minimumFractionDigits:digits,maximumFractionDigits:digits});

 function openBatch(type,id){
  const data=api.getData(),date=api.getDate(),existing=dayOf(data,date).events.find(e=>e.id===id),listKey=listKeys[type];
  if(!listKey)return false;
  const selected=new Map();let query='';
  const itemList=()=>{const list=[...data[listKey]];if(existing?.ref&&!list.some(x=>x.id===existing.ref))list.push({id:existing.ref,name:existing.name});return list;};
  const choose=item=>selected.set(item.id,{item,ml:item.ml||250,dose:item.dose||'',severity:2});
  if(existing){const item=itemList().find(x=>x.id===existing.ref);choose(item);Object.assign(selected.get(item.id),{ml:existing.ml||item.ml||250,dose:existing.dose||'',severity:existing.severity||2});}
  const recent=new Map();Object.keys(data.days).sort().slice(-30).forEach(d=>data.days[d].events.filter(e=>e.type===type).forEach(e=>recent.set(e.ref,(recent.get(e.ref)||0)+1)));
  const picker=()=>{
   const list=itemList().filter(x=>(x.name+' '+(x.group||'')).toLocaleLowerCase('pl').includes(query.toLocaleLowerCase('pl'))).sort((a,b)=>(recent.get(b.id)||0)-(recent.get(a.id)||0)||a.name.localeCompare(b.name,'pl'));
   return list.length?list.map(x=>`<button type="button" class="pick-item ${selected.has(x.id)?'selected':''}" data-pick="${esc(x.id)}" aria-pressed="${selected.has(x.id)}"><span class="pick-check" aria-hidden="true">${selected.has(x.id)?'✓':'+'}</span><span><strong>${esc(x.name)}</strong>${x.group?`<small>${esc(x.group)}</small>`:type==='med'&&x.dose?`<small>${esc(x.dose)}</small>`:type==='drink'?`<small>${x.ml} ml</small>`:''}</span></button>`).join(''):`<p class="muted small">${query?'Brak pasujących pozycji.':'Dodaj pierwszą pozycję poniżej.'}</p>`;
  };
  const chosen=()=>[...selected].map(([ref,s])=>`<section class="batch-detail" data-detail="${esc(ref)}"><div class="row between"><strong>${esc(s.item.name)}</strong></div>${type==='drink'?`<label class="field"><span>Ilość (ml)</span><input type="number" data-value="ml" data-ref="${esc(ref)}" name="ml-${esc(ref)}" value="${s.ml}" min="1" max="10000" required inputmode="numeric"></label><div class="chips">${[150,250,500].map(n=>`<button type="button" class="chip" data-portion="${n}" data-ref="${esc(ref)}">${n} ml</button>`).join('')}</div>`:type==='med'?`<label class="field"><span>Dawka (opcjonalnie)</span><input data-value="dose" data-ref="${esc(ref)}" name="dose-${esc(ref)}" value="${esc(s.dose)}" maxlength="200" placeholder="np. 1 tabletka"></label>`:type==='symptom'?`<fieldset><legend>Nasilenie</legend><div class="choices">${[[1,'łagodne'],[2,'umiarkowane'],[3,'silne']].map(([n,label])=>`<label class="choice"><input type="radio" data-value="severity" data-ref="${esc(ref)}" name="severity-${esc(ref)}" value="${n}" ${s.severity===n?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`:''}</section>`).join('');
  const newFields=`<details class="inline-create"><summary>Dodaj nową pozycję</summary>${textField('Nazwa','new-name','','np. '+(type==='symptom'?'Ból głowy':type==='med'?'Nazwa leku':'Nazwa'),'text','maxlength="200"')}${type==='symptom'?textField('Kategoria','new-group','Inne','','text','maxlength="200"'):type==='med'?textField('Domyślna dawka','new-dose','','np. 1 tabletka','text','maxlength="200"'):type==='drink'?textField('Domyślna porcja (ml)','new-ml',250,'','number','min="1" max="10000"'):''}<button type="button" class="secondary" id="batch-new">Dodaj i zaznacz</button></details>`;
  const linked=type==='activity'?data.habits.filter(h=>habitDue(h,date)):[];
  showModal(existing?'Edytuj wpis':CATEGORY_LABELS[type],`<p class="small muted">${existing?'Wybierz pozycję, którą chcesz zapisać.':'Zaznacz kilka pozycji i zapisz je jednym przyciskiem.'}</p><label class="field"><span class="visually-hidden">Szukaj pozycji</span><input type="search" id="batch-search" placeholder="Szukaj po nazwie…" autocomplete="off"></label><div id="batch-picker" class="pick-grid">${picker()}</div>${newFields}<div id="batch-chosen">${chosen()}</div><details class="batch-more" ${existing?'open':''}><summary>Godzina i notatka</summary>${textField('Godzina','time',existing?.time||clockNow(),'','time','required')}${textField('Notatka do wybranych wpisów','note',existing?.note||'','Opcjonalnie','textarea','maxlength="20000"')}<p class="small muted">${prettyDate(date)} · dzień dziennika kończy się o 4:00.</p></details>${linked.length?`<details class="batch-more"><summary>Odhacz również nawyk</summary><div class="choices">${linked.map(h=>`<label class="choice"><input type="checkbox" name="linked-habit" value="${esc(h.id)}"><span>${esc(h.name)}</span></label>`).join('')}</div></details>`:''}<label class="review-check"><input type="checkbox" name="reviewed" ${dayOf(data,date).reviewed?.[type]?'checked':''}><span>To komplet wpisów w tej kategorii za ten dzień<small>Pomaga w analizie. Zaznacz także wtedy, gdy nic nie wystąpiło i lista jest pusta.</small></span></label><div class="actions batch-actions">${btn('close-modal','Anuluj','text-btn')}<button type="submit" class="primary" id="batch-submit">${existing?'Zapisz zmianę':`Zapisz wybrane (${selected.size})`}</button></div>`,async fd=>{
   if(!selected.size&&!fd.has('reviewed'))throw Error('Zaznacz pozycję lub potwierdź komplet wpisów dla pustej listy.');
   if(existing&&!selected.size)throw Error('Wybierz pozycję. Do usuwania służy przycisk przy wpisie.');
   const time=fd.get('time'),note=fd.get('note').trim();
   const entries=[...selected].map(([ref,s])=>{
    if(type==='drink'&&(!Number.isFinite(s.ml)||s.ml<1||s.ml>10000))throw Error('Podaj ilość napoju od 1 do 10000 ml.');
    return {...(existing||{}),id:existing?.id||uid(),type,ref,name:s.item.name,time,note,timestamp:eventStamp(date,time),...(type==='drink'?{ml:s.ml}:type==='med'?{dose:s.dose.trim()}:type==='symptom'?{severity:s.severity}:{})};
   });
   const day=ensureDay(data,date);
   if(existing)day.events=day.events.map(e=>e.id===existing.id?entries[0]:e);else day.events.push(...entries);
   day.reviewed??={};day.reviewed[type]=fd.has('reviewed');
   for(const id of fd.getAll('linked-habit')){const h=data.habits.find(h=>h.id===id);if(!h||habitCount(data,h,date)>=h.target)continue;const checks=day.checks[id]??=[];if(h.mode==='weekly'){checks.push(true);continue;}const index=Array.from({length:h.target},(_,i)=>i).find(i=>!checks[i]);if(index!=null){while(checks.length<=index)checks.push(false);checks[index]=true;}}
   await persist({date});modal().close();render();toast(entries.length?`Zapisano ${entries.length===1?'wpis':'wpisów: '+entries.length}`:'Potwierdzono komplet wpisów');
  });
  const refresh=()=>{const focusId=document.activeElement?.dataset.pick;$('#batch-picker').innerHTML=picker();$('#batch-chosen').innerHTML=chosen();$('#batch-submit').textContent=existing?'Zapisz zmianę':`Zapisz wybrane (${selected.size})`;if(focusId)$$('[data-pick]').find(x=>x.dataset.pick===focusId)?.focus({preventScroll:true});};
  $('#batch-search').oninput=e=>{query=e.target.value;$('#batch-picker').innerHTML=picker();};
  $('#modal-form').addEventListener('input',e=>{const input=e.target;if(!input.dataset.value)return;const state=selected.get(input.dataset.ref);if(state)state[input.dataset.value]=input.dataset.value==='dose'?input.value:Number(input.value);});
  $('#modal-form').addEventListener('click',async e=>{
   const pick=e.target.closest('[data-pick]'),portion=e.target.closest('[data-portion]');
   if(pick){const ref=pick.dataset.pick;if(selected.has(ref)&&!existing)selected.delete(ref);else{if(existing)selected.clear();choose(itemList().find(x=>x.id===ref));}refresh();}
   if(portion){selected.get(portion.dataset.ref).ml=Number(portion.dataset.portion);refresh();}
   if(e.target.id==='batch-new'){
    const name=$('[name=new-name]').value.trim();if(!name){toast('Podaj nazwę nowej pozycji.');return;}
    const item={id:uid(),name};if(type==='symptom')item.group=$('[name=new-group]').value.trim()||'Inne';if(type==='med')item.dose=$('[name=new-dose]').value.trim();if(type==='drink'){item.ml=Number($('[name=new-ml]').value);if(!(item.ml>=1&&item.ml<=10000)){toast('Podaj porcję od 1 do 10000 ml.');return;}}
    e.target.disabled=true;try{data[listKey].push(item);await persist({date});if(existing)selected.clear();choose(item);query='';$('#batch-search').value='';$('[name=new-name]').value='';$('.inline-create').open=false;refresh();}catch(err){toast(err.message)}finally{e.target.disabled=false;}
   }
  });
  return true;
 }

 function historySwitch(){return `<div class="segment history-switch" aria-label="Widok historii">${[['memories','Wspomnienia'],['records','Wpisy i wykresy']].map(([value,label])=>btn('history-mode',label,historyMode===value?'active':'',`data-mode="${value}" aria-pressed="${historyMode===value}"`)).join('')}</div>`;}
 const photoDates=()=>Object.keys(api.getData().days).filter(d=>api.getData().days[d].journal.photo).sort().reverse();
 function memoryControls(){return `<div class="row between wrap"><div class="row">${btn('memory-prev',icon('left'),'icon-btn','aria-label="Poprzedni miesiąc wspomnień"')}<strong>${new Intl.DateTimeFormat('pl',{month:'long',year:'numeric'}).format(new Date(memoryMonth+'-01T12:00:00'))}</strong>${btn('memory-next',icon('right'),'icon-btn',`aria-label="Następny miesiąc wspomnień" ${memoryMonth>=effectiveDate().slice(0,7)?'disabled':''}`)}</div><div class="chips">${btn('memory-mode','Album',`chip ${memoryMode==='album'?'selected':''}`,'data-mode="album"')}${btn('memory-mode','Kalendarz',`chip ${memoryMode==='calendar'?'selected':''}`,'data-mode="calendar"')}</div></div>`;}
 function memoriesView(){
  const data=api.getData(),dates=photoDates(),shown=dates.filter(d=>memoryAll||d.startsWith(memoryMonth));
  const intro=`<div class="page-head"><p class="eyebrow">Zatrzymane chwile</p><h1>Do tego chcę wracać.</h1><p class="muted">Zdjęcia, dobre drobiazgi i Twoje słowa.</p></div>${historySwitch()}<section class="card memories">${memoryControls()}`;
  if(memoryMode==='calendar'){
   const first=memoryMonth+'-01',offset=(new Date(first+'T12:00:00').getDay()+6)%7,count=new Date(Number(memoryMonth.slice(0,4)),Number(memoryMonth.slice(5)),0).getDate();
   return intro+`<p class="small muted" style="margin-top:14px">Dotknij zdjęcia, aby otworzyć wspomnienie. Pusta kartka prowadzi do dziennika.</p><div class="photo-calendar">${['Pn','Wt','Śr','Cz','Pt','So','Nd'].map(x=>`<span class="day-name">${x}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const date=memoryMonth+'-'+String(i+1).padStart(2,'0'),j=dayOf(data,date).journal;return `<button type="button" class="photo-day ${j.photo?'with-photo':''}" data-action="memory-day" data-date="${date}" aria-label="${prettyDate(date)}${j.photo?', otwórz zdjęcie':''}" ${date>effectiveDate()?'disabled':''}>${j.photo?`<img src="${j.photo}" alt="" loading="lazy">`:''}<span>${i+1}</span></button>`}).join('')}</div>${dates.length?'':'<p class="small muted" style="margin-top:18px">Dodaj zdjęcie w Dzienniku. Pojawi się tutaj przy dacie wpisu.</p>'}</section>`;
  }
  return intro+`<div class="chips" style="margin:18px 0">${btn('memory-scope','Wszystkie zdjęcia',`chip ${memoryAll?'selected':''}`,'data-all="true"')}${btn('memory-scope','Wybrany miesiąc',`chip ${!memoryAll?'selected':''}`,'data-all="false"')}</div>${shown.length?`<div class="photo-album">${shown.map(date=>{const j=dayOf(data,date).journal,caption=j.pleasant1||j.notes||'Otwórz wspomnienie';return `<button type="button" class="memory-card" data-action="memory-open" data-date="${date}"><img src="${j.photo}" loading="lazy" alt="Zdjęcie z ${prettyDate(date)}"><span class="memory-caption"><time datetime="${date}">${prettyDate(date)} ${date.slice(0,4)}</time><span>${esc(caption.slice(0,130))}${caption.length>130?'…':''}</span></span></button>`}).join('')}</div>`:`<div class="empty">${icon('camera')}<h2>Twoje wspomnienia mają tu miejsce.</h2><p>${dates.length?'W tym miesiącu nie ma jeszcze zdjęć.':'Dodaj zdjęcie dnia w Dzienniku, a tutaj powstanie Twój album.'}</p>${btn('journal','Otwórz dziennik','secondary')}</div>`}</section>`;
 }
 function openMemory(date){
  photoDate=date;const j=dayOf(api.getData(),date).journal,dates=photoDates(),index=dates.indexOf(date);if(!j.photo)return;
  showModal(`${prettyDate(date)} ${date.slice(0,4)}`,`<img class="memory-full" src="${j.photo}" alt="Zdjęcie z ${prettyDate(date)}"><p class="eyebrow">${weekday(date)}</p>${[1,2,3].filter(n=>j['pleasant'+n]).map(n=>`<p class="history-summary">${esc(j['pleasant'+n])}</p>`).join('')}${j.notes?`<p class="history-summary muted">${esc(j.notes)}</p>`:''}<div class="row between wrap"><div class="row">${btn('photo-older',icon('left'),'icon-btn',`aria-label="Starsze zdjęcie" ${index>=dates.length-1?'disabled':''}`)}<span class="small muted">${index+1} / ${dates.length}</span>${btn('photo-newer',icon('right'),'icon-btn',`aria-label="Nowsze zdjęcie" ${index<=0?'disabled':''}`)}</div>${btn('memory-journal','Otwórz całą kartkę','secondary',`data-date="${date}"`)}</div>`+actions('Zamknij'),()=>modal().close());modal().classList.add('memory-dialog');
 }
 function comparisonCard(result,outcomeIsSymptom){
  const ratio=n=>outcomeIsSymptom?fmt(n*100,0)+'%':fmt(n);
  const stats=`<div class="compare-grid"><div><span class="small muted">Dni z zapisanym zdarzeniem</span><strong>${ratio(result.a)}</strong><small>${result.withFactor.length} dni</small></div><div><span class="small muted">Dni z potwierdzonym brakiem</span><strong>${ratio(result.b)}</strong><small>${result.withoutFactor.length} dni</small></div></div>`;
  return stats+(result.ready?`<p class="association-result">Różnica: ${result.difference>0?'+':''}${outcomeIsSymptom?fmt(result.difference*100,0)+' p.p.':fmt(result.difference)+' pkt'}</p>`:`<p class="data-threshold">Za mało danych do porównania. Potrzeba co najmniej 5 dni w każdej grupie; teraz ${result.withFactor.length} i ${result.withoutFactor.length}.</p>`)+`<p class="small muted">${result.excluded} dni pominięto z powodu brakujących pomiarów lub niepotwierdzonych wpisów. ${outcomeIsSymptom?'Procent oznacza udział dni z zapisanym objawem.':'Wartości to średnie dzienne. Każdy dzień ma tę samą wagę.'}</p>`;
 }
 function analysisView(){
  const data=api.getData(),end=api.getDate(),factors=recordedFactors(data);if(!factors.some(x=>x.key===factorKey))factorKey=factors[0]?.key||'';
  const factor=factors.find(x=>x.key===factorKey),outcomeFactor=outcomeKey.startsWith('symptom:')?factors.find(x=>x.key===outcomeKey):null;if(outcomeKey.startsWith('symptom:')&&!outcomeFactor)outcomeKey='mood';
  const outcome=outcomeFactor||outcomeKey,rows=rangeRows(data,end,analysisRange),daysWithMood=rows.filter(r=>r.mood!=null).length;
  const numericKey=typeof outcome==='string'?outcome:'mood',relations=numericRelations(data,end,analysisRange,numericKey),comparison=factor?compareDays(data,end,analysisRange,factor,outcome,lag):null,around=factor?beforeAfter(data,end,analysisRange,factor,numericKey):null;
  return `${api.header('Co układa się we wzór?','Zależności w Twoich zapisach, z miejscem na kontekst.')}<div class="segment analysis-range">${[7,30,90].map(n=>btn('analysis-range',`${n} dni`,analysisRange===n?'active':'',`data-range="${n}"`)).join('')}</div><div class="banner">To analiza obserwacyjna: współwystępowanie nie oznacza przyczyny. Sen, pora dnia i inne zdarzenia mogą zmieniać wyniki. Nie zmieniaj leków na podstawie tych porównań.</div><div class="metric-row"><div class="metric"><strong>${daysWithMood}<small> / ${analysisRange}</small></strong><span>Dni z pomiarem nastroju</span></div><div class="metric"><strong>${factors.length}</strong><span>Różnych zapisanych zdarzeń</span></div></div><section class="card" style="margin:20px 0"><h2>Porównaj dni</h2><p class="small muted">Wybierz lek, objaw, napój lub zdarzenie oraz to, co chcesz z nim zestawić.</p><div class="grid"><label class="field"><span>Zdarzenie</span><select id="analysis-factor"><option value="">${factors.length?'Wybierz zdarzenie':'Najpierw dodaj wpisy w zakładce Dziś'}</option>${factors.map(f=>`<option value="${esc(f.key)}" ${f.key===factorKey?'selected':''}>${CATEGORY_LABELS[f.type]} · ${esc(f.name)}</option>`).join('')}</select></label><label class="field"><span>Z czym porównać?</span><select id="analysis-outcome">${Object.entries(MEASURES).filter(([k])=>!['water','sleepHours'].includes(k)).map(([k,n])=>`<option value="${k}" ${k===outcomeKey?'selected':''}>${n}</option>`).join('')}${factors.filter(f=>f.type==='symptom').map(f=>`<option value="${esc(f.key)}" ${f.key===outcomeKey?'selected':''}>Objaw · ${esc(f.name)}</option>`).join('')}</select></label></div><div class="chips" style="margin-bottom:20px">${btn('analysis-lag','Ten sam dzień',`chip ${lag===0?'selected':''}`,'data-lag="0"')}${btn('analysis-lag','Następny dzień',`chip ${lag===1?'selected':''}`,'data-lag="1"')}</div>${factor?(factor.key===outcomeKey?'<p class="data-threshold">Wybierz dwa różne czynniki — porównanie objawu z samym sobą nie wnosi informacji.</p>':comparisonCard(comparison,!!outcomeFactor)):'<p class="empty">Po pierwszych zapisach pojawią się tutaj Twoje leki, objawy i zdarzenia.</p>'}<details><summary class="small">Jak liczymy dni bez zdarzenia?</summary><p class="small muted" style="margin-top:12px">Brak wpisu nie jest zerem. Do drugiej grupy trafiają tylko dni, w których potwierdziłeś komplet wpisów dla danej kategorii, a wybranej pozycji nie ma. Zrobisz to na dole formularza dodawania. Przy porównaniu z objawem jego brak też wymaga potwierdzenia kategorii Objawy. „Następny dzień” zestawia zdarzenie z poprzedniego dnia z wynikiem dnia wyświetlanego w tabeli.</p></details>${comparison&&(comparison.withFactor.length||comparison.withoutFactor.length)&&factor.key!==outcomeKey?`<details style="margin-top:14px"><summary class="small">Dni użyte w porównaniu</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Dzień wyniku</th><th>Zdarzenie</th><th>Wartość</th></tr></thead><tbody>${[...comparison.withFactor.map(r=>({...r,group:'z wpisem'})),...comparison.withoutFactor.map(r=>({...r,group:'potwierdzony brak'}))].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${r.date}</td><td>${r.group}</td><td>${outcomeFactor?(r.value?'objaw zapisany':'potwierdzony brak'):fmt(r.value)}</td></tr>`).join('')}</tbody></table></div></details>`:''}</section><div class="grid"><section class="card"><h2>Co zmienia się razem?</h2><p class="small muted">Zestawienie z: ${MEASURES[numericKey]}. Korelacja rangowa opisuje, czy wyższym wartościom towarzyszą wyższe lub niższe wartości drugiego pomiaru.</p>${relations.map(r=>`<div class="relation-row"><div><strong>${MEASURES[r.key]}</strong><small>${r.n} wspólnych dni</small></div><span>${r.ready?`ρ = ${fmt(r.rho,2)}`:r.n<10?'Potrzeba 10 dni':'Brak zmienności'}</span>${r.ready?`<div class="rho-track" aria-hidden="true"><i style="width:${Math.abs(r.rho)*50}%;left:${r.rho<0?50-Math.abs(r.rho)*50:50}%"></i></div><small class="muted">${Math.abs(r.rho)<.2?'Brak wyraźnego kierunku w tych danych':r.rho>0?'Wartości zwykle rosną razem':'Wyższym wartościom jednej odpowiadają niższe drugiej'}</small>`:''}</div>`).join('')}<p class="small muted" style="margin-top:16px">ρ od −1 do +1. To opis Twojej próby, bez testu istotności ani korekty innych czynników. Próg 10 dni służy wyłącznie ograniczeniu przypadkowych wyników; nie gwarantuje wiarygodności.</p></section><section class="card"><h2>Przed i po zdarzeniu</h2><p class="small muted">${factor?esc(factor.name):'Wybierz zdarzenie powyżej'} · ${MEASURES[numericKey]}</p>${around&&['mood','energy','productivity'].includes(numericKey)?`<div class="compare-grid"><div><span class="small muted">Przed</span><strong>${fmt(around.before)}</strong></div><div><span class="small muted">Po</span><strong>${fmt(around.after)}</strong></div></div>${around.ready?`<p class="association-result">Średnia zmiana: ${around.difference>0?'+':''}${fmt(around.difference)} pkt</p>`:`<p class="data-threshold">Potrzeba 5 dni z parą pomiarów. Na razie: ${around.pairs.length}.</p>`}<p class="small muted">Najbliższy pomiar do 3 godzin przed i do 3 godzin po pierwszym takim zdarzeniu w danym dniu. Pomijamy parę, jeśli w jej przedziale powtórzono to samo zdarzenie. Maksymalnie jedna para na dzień. ${around.pairs.length} dni w próbie.</p>`:'<p class="empty">Dostępne dla nastroju, energii i produktywności mierzonych w ciągu dnia.</p>'}<p class="small muted">Zmiana po zdarzeniu nie dowodzi jego działania. Inne leki i wydarzenia mogły wystąpić w tym samym czasie.</p></section></div>`;
 }
 async function handleAction(action,target){
  if(action==='history-mode'){historyMode=target.dataset.mode;render();}
  else if(action==='memory-mode'){memoryMode=target.dataset.mode;render();}
  else if(action==='memory-scope'){memoryAll=target.dataset.all==='true';render();}
  else if(action==='memory-prev'||action==='memory-next'){const d=new Date(memoryMonth+'-01T12:00:00');d.setMonth(d.getMonth()+(action==='memory-prev'?-1:1));memoryMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;memoryAll=false;render();}
  else if(action==='memory-open')openMemory(target.dataset.date);
  else if(action==='memory-day'){const date=target.dataset.date;if(dayOf(api.getData(),date).journal.photo)openMemory(date);else{api.setDate(date);navigate('journal');}}
  else if(action==='photo-older'||action==='photo-newer'){const dates=photoDates(),i=dates.indexOf(photoDate),next=dates[i+(action==='photo-older'?1:-1)];if(next)openMemory(next);}
  else if(action==='memory-journal'){modal().close();api.setDate(target.dataset.date);navigate('journal');}
  else if(action==='analysis-range'){analysisRange=Number(target.dataset.range);render();}
  else if(action==='analysis-lag'){lag=Number(target.dataset.lag);render();}
  else return false;
  return true;
 }
 document.addEventListener('change',e=>{if(e.target.id==='analysis-factor'){factorKey=e.target.value;render();}else if(e.target.id==='analysis-outcome'){outcomeKey=e.target.value;render();}});
 return {openBatch,handleAction,historySwitch,memoriesView,analysisView,isMemories:()=>historyMode==='memories'};
}
